using EnterpriseDocumentIntelligence.BuildingBlocks.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
[ApiController,Route("api/v1/search"),Authorize]public sealed class SearchController(HybridSearchApplication app,ICurrentUser user,ILogger<SearchController> log):ControllerBase{[HttpPost]public async Task<ActionResult<IReadOnlyList<SearchHit>>>Search(SearchQuery request,CancellationToken ct){var result=await app.SearchAsync(user.TenantId,user.UserId,request,ct);log.LogInformation("Hybrid search Tenant={TenantId} Results={Count}",user.TenantId,result.Count);return Ok(result);}}